interface RectAnnotationDatum {
  coordinates: {
    x0?: PrimitiveValue;
    x1?: PrimitiveValue;
    y0?: PrimitiveValue;
    y1?: PrimitiveValue;
  };
  details?: string;
}

type PrimitiveValue = string | number | null;
